      if (n & 0x8000) (n = ((n & 0x7fff) << 16) | v.getUint16(o + 2, true)), (o += 4);
      else o += 2;
      let s = '';
      for (let j = 0; j < n; j++) s += String.fromCharCode(v.getUint16(o + j * 2, true));
      out[i] = s;
