/** Default (no locale) string of a resource, else the first one. */
export function resString(table: ResTable | null, v: Value | undefined): string | null {
  if (!v) return null;
  if (v.type !== T_REFERENCE) return attrText(v);
  const list = table?.resolve(v.data).filter((r) => r.str !== null) ?? [];
  return (list.find((r) => !r.lang) ?? list[0])?.str ?? null;
}

/** File paths of a drawable/mipmap resource, highest density first (anydpi = 0xfffe sorts first). */
export function resFiles(table: ResTable | null, id: number): string[] {
  const list = table?.resolve(id).filter((r) => r.str) ?? [];
  return [...new Set(list.sort((a, b) => b.density - a.density).map((r) => r.str!))];
}
